from pathlib import Path
from html import escape as h
import json
from app_shell import home_page, theme_styles, THEME_CONTROL, BOOTSTRAP
from components import svg
R=Path(__file__).resolve().parents[1]/'assets'
def render(data):
    slides,questions=data['slides'],data['questions']
    source_items=''.join('<li>'+('<a href="'+h(item['url'],quote=True)+'">'+h(item['title'])+'</a>' if item.get('url') else h(item['title'])+' (제공 자료)')+'</li>' for item in data['sources'])
    published=data['published_lessons']
    home=home_page(data,svg(0,slides[0]).replace('slide-title-0','home-preview-title').replace('slide-desc-0','home-preview-desc'))
    toc='<h2 class="toc-title">강의 목차</h2>'
    section=None
    for item in data['course_lessons']:
        if section!=item['section']:
            section=item['section'];toc+='<h3>'+h(section)+'</h3>'
        active=item['id']==data['lesson_id']
        toc+='<button type="button" class="lesson-link'+(' active' if active else '')+'" data-course-jump="'+item['id']+'"'+(' aria-current="page"' if active else '')+'><span class="lesson-check" data-course-check="'+item['id']+'" aria-label="완료 표시 없음"></span><span><b>'+h(item['title'])+'</b><small>'+h(item['kind_label'])+'</small></span></button>'
    slide_html=''.join(f'<article class="lesson-slide" data-slide="{i}"'+(' hidden' if i else '')+'>'+svg(i,s)+'</article>' for i,s in enumerate(slides))
    thumbs=''.join(f'<button type="button" class="thumb'+(' current' if i==0 else '')+f'" data-thumb="{i}" aria-label="{i+1}장: {h(s["title"])}"><small>{i+1:02d}</small><b>{h(s["title"])}</b></button>' for i,s in enumerate(slides))
    quiz=''
    for q in questions:
        quiz += f'<fieldset><legend>{h(q["prompt"])}</legend>'+''.join(f'<label class="choice"><input type="radio" name="{q["id"]}" value="{v}"> {h(t)}</label>' for v,t in q['choices'])+f'<p id="feedback-{q["id"]}" role="status"></p><details><summary>해설 보기</summary><p>{h(q["explanation"])}</p></details></fieldset>'
    overrides='''
    [hidden]{display:none!important}.icon-button svg,.icon-button svg *{pointer-events:none}button,input,textarea{font:inherit}button:focus-visible,a:focus-visible,[tabindex]:focus-visible{outline:3px solid #92c4ff;outline-offset:3px}
    body{font-size:17px}button{font-size:16px}header{align-items:center;padding:14px 24px}header h1{font-size:18px;flex:1}header .course-brand{font-size:14px;color:#9fb0c6;letter-spacing:.07em}
    #progress{padding:11px 24px;gap:12px}#progress .bar{max-width:260px}#progress .label{font-size:14px}#progress .position-label{margin-left:auto}
    main#course-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:22px;padding:22px;max-width:1680px;margin:auto;align-items:start}
    aside#toc{display:block;border:1px solid #242d3a;border-radius:10px;position:sticky;top:18px;max-height:calc(100vh - 40px);padding:20px 12px}
    #toc .toc-title{font-size:17px;margin:0 8px 18px;color:#f4f7fb}#toc h3{font-size:14px;letter-spacing:.06em;margin:22px 8px 12px}
    .lesson-link{display:flex;gap:12px;width:100%;text-align:left;align-items:flex-start;background:transparent;border:0;padding:12px 9px;margin:4px 0;color:#aab8ca;line-height:1.5}
    .lesson-link.active{background:#1a2e4a;border-left:3px solid #5793e6;padding-left:6px;color:#fff}.lesson-check{width:17px;height:17px;flex:0 0 17px;border:1px solid #556881;border-radius:50%;text-align:center;font-size:14px;line-height:15px;margin-top:3px;color:#8de1b6}.lesson-link b{display:block;font-size:15px;font-weight:500}.lesson-link small{display:block;color:#8497ae;font-size:14px;margin-top:5px}
    .toc-note{font-size:14px;color:#8190a4;margin:20px 8px 5px}.player-column{min-width:0}#lesson-heading{margin:0 0 14px;font-size:22px;font-weight:600;line-height:1.45}
    #stage{padding:12px;border:1px solid #232c3a;border-radius:12px;gap:8px}#slide-wrap{aspect-ratio:16/9;background:#fff;position:relative}.lesson-slide{width:100%;height:100%;display:block}.lesson-slide svg{width:100%;height:100%;display:block}
    #video-wrap{aspect-ratio:16/9;background:#080b11;border-radius:8px;display:flex;align-items:center;justify-content:center;overflow:hidden}#lesson-video{width:100%;height:100%;object-fit:contain}
    #controls{padding:7px 2px;flex-wrap:wrap}#play{background:#4b87df;color:#fff;min-width:86px}#stage-play{position:absolute;inset:0;margin:auto;width:86px;height:86px;border-radius:50%;background:#172c48e8;color:white;font-size:36px;border:2px solid #ffffff99;box-shadow:0 4px 24px #0006}#voice-state{font-size:14px;color:#9faec1;margin:6px 4px}#speed{padding:6px;background:#172333;color:#fff;border:1px solid #455970;border-radius:5px}.tx-cue{display:block;width:100%;text-align:left;font:inherit;color:inherit;background:transparent;border:0;border-left:3px solid transparent;border-radius:0;padding:8px 12px;margin:3px 0;line-height:1.8}.tx-cue.active{background:#21344e;border-left-color:#7bb1fc;color:#fff}#audio-seek{width:100%;accent-color:#6da4f5}#audio-time{font-size:14px;font-variant-numeric:tabular-nums}#pos{font-variant-numeric:tabular-nums}.fullscreen-control{margin-left:8px}.fullscreen-control button{padding:7px 11px}
    #thumbs{margin:0 -12px -12px;padding:12px;gap:8px;border-radius:0 0 12px 12px}button.thumb{display:flex;flex-direction:column;text-align:left;gap:5px;padding:9px;width:125px;flex:0 0 125px;aspect-ratio:16/9;white-space:normal;background:#eaf0f6;color:#1e314a;border:2px solid transparent;border-radius:5px;line-height:1.3}
    button.thumb.current{border-color:#5b9bf3;background:#fff}button.thumb small{font-size:14px;color:#627890}button.thumb b{font-size:14px;font-weight:600}
    .lesson-actions{display:flex;gap:16px;align-items:center;justify-content:space-between;padding:17px 0;color:#b6c3d4;font-size:15px}.lesson-actions input{accent-color:#4f8ee9}.lesson-actions button{background:transparent}
    #materials{margin-top:12px;border-top:1px solid #27303e}.tabs{display:flex;gap:24px;border-bottom:1px solid #27303e}.tabs button{padding:16px 0;background:transparent;border:0;border-radius:0;color:#879ab2;font-size:16px;white-space:nowrap}.tabs button[aria-selected="true"]{color:#f3f6fb;border-bottom:2px solid #609dee}
    .material-panel{padding:20px 2px 30px;line-height:1.85;color:#bcc9da;max-width:100%}.material-panel h2{font-size:19px;color:#eaf0f8;margin:0 0 12px}.material-panel p{margin:0 0 14px;font-size:16px}.material-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.6}.material-panel ul{padding-left:20px}.material-panel fieldset{border:1px solid #344054;border-radius:8px;padding:20px;margin:12px 0 22px;min-width:0}.material-panel legend{font-size:16px;color:#eaf0f8;font-weight:600;line-height:1.8;padding:0 8px}.choice{display:block;margin:10px 0;padding:8px;background:#181f2c;border-radius:6px}.material-panel textarea{display:block;width:100%;max-width:100%;padding:12px;min-height:90px;background:#121824;color:#dae4f2;border:1px solid #3c4d65;border-radius:8px;font:inherit}.material-panel label{display:block}.state-actions{display:flex;gap:12px;margin:14px 0}#quiz-result,[id^="feedback-"]{color:#9fc7ff}#tx-copy{max-width:900px}details summary{cursor:pointer}#end-panel{padding:16px;margin:4px 0}#end-panel h2{font-size:19px}#end-panel p{margin:8px 0;color:#b7c9e1;font-size:15px}
    .site-footer{font-size:14px;color:#77899f;text-align:center;padding:20px;border-top:1px solid #222c39}.skip-link{position:absolute;top:-60px;left:16px;z-index:150;background:#fff;color:#16253b;padding:10px}.skip-link:focus{top:10px}#player-status{font-size:14px;color:#a6b7cf}
    #slide-wrap:fullscreen{width:100vw;height:100vh;aspect-ratio:auto;background:#000}#slide-wrap:fullscreen .lesson-slide{display:flex;align-items:center;justify-content:center}#slide-wrap:fullscreen svg{object-fit:contain;max-height:100vh}#video-wrap:fullscreen{width:100vw;height:100vh;aspect-ratio:auto}
    @media(max-width:980px){main#course-layout{grid-template-columns:190px minmax(0,1fr);gap:14px;padding:14px}aside#toc{display:block;position:sticky;width:auto;height:auto;max-height:calc(100vh - 30px)}#lesson-heading{font-size:19px}header{padding:12px 16px}#progress{padding:10px 16px}}
    @media(min-width:701px){#menu-toggle{display:none}}@media(max-width:700px){main#course-layout{grid-template-columns:minmax(0,1fr);padding:10px;gap:0}aside#toc{display:none}aside#toc.open{display:block;position:fixed;top:0;left:0;width:270px;height:100dvh;max-height:100dvh;z-index:100;border-radius:0;box-shadow:0 0 0 100vmax #0008;padding-top:24px}header h1{font-size:15px}.course-brand{display:none}#progress .position-label,#slide-progress-bar{display:none}#progress .bar{max-width:none}#stage{padding:7px}#thumbs{margin:0 -7px -7px;padding:9px}#controls{gap:6px}#controls button{padding:7px 9px;font-size:14px}.lesson-actions{flex-wrap:wrap;gap:8px}.tabs{gap:20px;overflow-x:auto}.tabs button{font-size:15px}.material-panel{padding:16px 2px}#pos{font-size:14px}.fullscreen-control{margin-left:0}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
    '''
    license_text=(R/'LICENSE-course-builder.txt').read_text()
    core=(R/'course-core.js').read_text()
    model=(R/'player-model.js').read_text()
    script=(R/'player.js').read_text()
    narration_script=(R/'narration-player.js').read_text()
    video_script=(R/'native-video-player.js').read_text()
    presentation_script=(R/'presentation-model.js').read_text()
    controls_script=(R/'controls-ui.js').read_text()
    seek_script=(R/'seek-preview.js').read_text()
    shell_model=(R/'course-shell-model.js').read_text()
    theme_script=(R/'html-theme.js').read_text()
    all_css=theme_styles((R/'reference-player.css').read_text()+'\n'+overrides,R)
    html=f'''<!doctype html><html lang="ko" data-course-build="1" data-default-theme="system"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{h(data['title'])}</title><script>{BOOTSTRAP}</script><style>{all_css}</style></head><body>
    <!-- Player shell CSS adapted from tobyilee/course-builder at 1913b09bd1bf947b5ee2d1a75eab4396e669fbd3.\n{license_text} -->
    <a class="skip-link" id="skip-main" href="#home-title">본문으로 이동</a>
    <header><button id="menu-toggle" type="button" aria-label="강의 목차 열기 또는 닫기" aria-controls="toc" aria-expanded="false" data-js-only hidden>☰</button><a class="site-brand" href="#home" data-home><span>{h(data['course_label'])}</span></a><p class="header-title">{h(data['title'])}</p><a id="back-home" href="#home" data-home hidden>← 코스 홈</a><div class="ht-document-actions course-header-actions">{THEME_CONTROL}</div></header>
    {home}<section id="player-page" aria-label="강의 플레이어" hidden><span id="lesson-slides"></span><div id="progress"><span class="label">완료로 표시한 강의 <strong id="completion-count">0 / 2</strong></span><div class="bar"><div class="fill" id="course-fill" style="width:0%"></div></div><span class="label position-label" id="slide-num">1 / 5</span><div class="bar" id="slide-progress-bar"><div class="fill" id="slide-fill" style="width:20%"></div></div></div>
    <main id="course-layout"><aside id="toc" aria-label="강의 목차">{toc}</aside>
    <div class="player-column"><h1 id="lesson-heading" tabindex="-1">{h(data['lesson_title'])}</h1><section id="voice-fallback" aria-label="강의 음성 준비 상태" hidden><p role="status"><span aria-hidden="true">⚠️</span> <span id="voice-preflight-message">생성 음성이 준비되지 않았습니다.</span></p><div class="voice-actions"><button id="use-silent" type="button">무음으로 재생</button><button id="use-browser-voice" type="button">브라우저 음성</button></div></section><div id="stage"><div id="media-viewport"><div id="slide-wrap" tabindex="0" role="region" aria-label="현재 슬라이드. 스페이스로 재생하거나 멈추고 좌우 화살표로 이동합니다.">{slide_html}</div><div id="video-wrap" hidden><video id="lesson-video" controls preload="metadata" src="{h(data['video_lesson'].get('src',''),quote=True)}" poster="{h(data['video_lesson'].get('poster',''))}" aria-label="{h(data['lesson_title'])}"></video></div><div id="live-caption" aria-label="강의 자막" hidden><p id="caption-text"></p></div></div>
    <div id="audio-progress" role="group" aria-label="강의 설명 진행" data-js-only hidden><div id="seek-preview" class="seek-preview" data-kind="slides" data-loading="false" data-error="false" aria-hidden="true" hidden><div class="seek-preview-visual"><div id="seek-preview-slide"></div><video id="seek-preview-video" muted playsinline preload="none" tabindex="-1"></video><span class="seek-preview-loading">미리보기 불러오는 중</span><span class="seek-preview-error">프레임 미리보기 없음</span></div><p id="seek-preview-position"></p><p id="seek-preview-caption"></p></div><input id="audio-seek" type="range" min="0" max="1" step="any" value="0" aria-label="강의 설명 재생 위치" aria-describedby="audio-time progress-kind"><div class="playback-progress-meta"><span id="audio-time"></span><span id="progress-kind"></span></div></div>
    <div id="controls" data-js-only hidden><div class="controls-left"><button id="stage-play" type="button" hidden aria-label="강의 재생">▶</button><button id="prev" type="button" class="icon-button" aria-label="이전 장" title="이전 장" disabled></button><button id="play" type="button" class="icon-button" aria-label="재생" title="재생"></button><button id="next" type="button" class="icon-button" aria-label="다음 장" title="다음 장"></button><span id="pos">1 / 5</span><div class="volume-control"><button id="mute-toggle" type="button" class="icon-button" aria-label="음소거" title="음소거 해제" aria-pressed="true"></button><label class="volume-slider"><span class="ht-visually-hidden">볼륨</span><input id="volume" type="range" min="0" max="100" step="1" value="100" aria-label="볼륨" aria-valuetext="100%, 음소거"></label></div></div><div class="controls-right"><button id="captions-toggle" type="button" class="icon-button" aria-label="자막 숨기기" title="자막 숨기기" aria-pressed="true" aria-controls="live-caption"></button><button id="caption-size-toggle" type="button" class="icon-button" aria-label="자막 크기 선택" title="자막 크기 선택" aria-expanded="false" aria-controls="caption-size-panel"></button><button id="speed" type="button" value="1" class="rate-button" aria-label="재생 속도 1배, 속도 선택 열기" title="재생 속도 선택" aria-expanded="false" aria-controls="speed-panel"><span id="speed-icon" aria-hidden="true"></span><span id="speed-label">1×</span><small id="speed-pending" hidden>예약</small></button><button id="transcript-toggle" type="button" class="icon-button" aria-label="전체 대본 열기" title="전체 대본 열기" aria-expanded="false" aria-controls="transcript-rail"></button><button id="settings-toggle" type="button" class="icon-button" aria-label="재생 설정 열기" title="재생 설정 열기" aria-expanded="false" aria-controls="playback-settings"></button><button id="fullscreen" type="button" class="icon-button" aria-label="전체 화면" title="전체 화면"></button></div></div><fieldset id="caption-size-panel" class="caption-size-panel" aria-label="자막 크기" hidden><legend class="ht-visually-hidden">자막 크기</legend><label class="speed-choice"><input type="radio" name="caption-size" value="small"><span>작게</span></label><label class="speed-choice"><input type="radio" name="caption-size" value="default" checked><span>기본</span></label><label class="speed-choice"><input type="radio" name="caption-size" value="large"><span>크게</span></label></fieldset><fieldset id="speed-panel" class="speed-panel" aria-label="재생 속도" hidden><legend class="ht-visually-hidden">재생 속도</legend><label class="speed-choice"><input type="radio" name="playback-speed" value="0.75"><span>0.75×</span></label><label class="speed-choice"><input type="radio" name="playback-speed" value="1" checked><span>1×</span></label><label class="speed-choice"><input type="radio" name="playback-speed" value="1.25"><span>1.25×</span></label><label class="speed-choice"><input type="radio" name="playback-speed" value="1.5"><span>1.5×</span></label><label class="speed-choice"><input type="radio" name="playback-speed" value="2"><span>2×</span></label></fieldset><section id="playback-settings" class="settings-panel" aria-label="재생 설정" hidden><div class="playback-settings-grid"><label for="caption-opacity">자막 배경</label><span class="caption-opacity-control"><input id="caption-opacity" type="range" min="0" max="100" step="5" value="50" aria-label="자막 배경 불투명도"><output id="caption-opacity-value" for="caption-opacity">50%</output></span><label for="voice-mode">강의 음성</label><select id="voice-mode"><option value="assets" selected>생성 음성 (기본)</option><option value="device">브라우저 음성 (폴백)</option><option value="silent">무음</option></select><label for="slide-pause">슬라이드 전환 후</label><span><input id="slide-pause" type="number" min="0" max="5" step="0.1" value="1.2"> 초</span><label for="sentence-pause">문장 사이</label><span><input id="sentence-pause" type="number" min="0" max="5" step="0.1" value="0.6"> 초</span><label for="silent-hold">무음 설명 간격</label><span><input id="silent-hold" type="number" min="1" max="15" step="0.5" value="4"> 초</span><label for="motion-mode">화면 표시</label><select id="motion-mode"><option value="on" selected>설명 따라 펼치기</option><option value="highlight">강조만 표시</option><option value="off">모두 보기</option></select></div><p>첫 재생은 바로 시작하며, 이후 쉼은 배속과 관계없이 유지됩니다.</p><p id="volume-note"></p><div class="browser-voice-setting"><label for="browser-voice">브라우저 음성</label><select id="browser-voice"><option value="">자동 선택</option></select><p id="voice-state"></p><p id="voice-selection-reason"></p><p>로컬 한국어 음성에서 기기 기본 음성을 우선 선택합니다. 없으면 목록의 첫 음성을 사용합니다. 음질 비교 결과는 아닙니다.</p></div></section><div id="end-panel"><h2>이제 다른 응답 순서에서도 예측해 보세요.</h2><p>이해 확인에서 새로운 응답 순서를 예측하고, 코스 홈에서 학습 진도를 확인하세요.</p><button id="end-next" type="button">완료로 표시하고 코스 홈</button></div></div><nav id="thumbs" aria-label="슬라이드 선택" data-js-only hidden>{thumbs}</nav>
    <p id="player-status" role="status"></p><div class="lesson-actions" data-js-only hidden><label><input id="mark-complete" type="checkbox"> 이 강의를 완료로 표시</label><span id="lesson-kind"></span><button id="next-lesson" type="button">다음 강의</button></div>
    <section id="materials" aria-label="현재 강의의 보조 자료"><div class="tabs" id="tabs" role="tablist" aria-label="강의 자료" data-js-only hidden><button role="tab" id="tab-notes" data-tab="notes" aria-controls="panel-notes" aria-selected="true">강의 노트</button><button role="tab" id="tab-transcript" data-tab="transcript" aria-controls="panel-transcript" aria-selected="false" tabindex="-1">대본</button><button role="tab" id="tab-quiz" data-tab="quiz" aria-controls="panel-quiz" aria-selected="false" tabindex="-1">이해 확인</button><button role="tab" id="tab-my-note" data-tab="my-note" aria-controls="panel-my-note" aria-selected="false" tabindex="-1">내 메모</button><button role="tab" id="tab-sources" data-tab="sources" aria-controls="panel-sources" aria-selected="false" tabindex="-1">참고 자료</button></div>
    <div class="material-panel" id="panel-notes" role="tabpanel" aria-labelledby="tab-notes" data-panel="notes"><h2>이 강의에서 배우는 내용</h2><p id="reading-note">{h(data['lessons'][0]['note'])}</p><ul><li>응답 순서가 뒤바뀐 상황에서 마지막 화면을 예측합니다.</li><li>요청 중단과 결과 반영 조건의 역할을 구분합니다.</li></ul><p>오류 처리와 effect 정리, 언마운트 및 데이터 캐시 정책은 요청 ID 검사와 함께 설계합니다.</p></div>
    <div class="material-panel" id="panel-transcript" role="tabpanel" aria-labelledby="tab-transcript" data-panel="transcript" hidden><h2 id="tx-title">{h(slides[0]['title'])}</h2><div id="tx-copy">{h(slides[0]['transcript'])}</div></div>
    <div class="material-panel" id="panel-quiz" role="tabpanel" aria-labelledby="tab-quiz" data-panel="quiz" hidden><h2>이해 확인</h2><form id="quiz-form" onsubmit="return false">{quiz}<button type="button" id="grade">답 확인 / 다시 채점</button><p id="quiz-result" role="status"></p></form></div>
    <div class="material-panel" id="panel-my-note" role="tabpanel" aria-labelledby="tab-my-note" data-panel="my-note" hidden><label for="memo">다시 확인할 내용과 예측의 근거를 기록합니다.</label><textarea id="memo" maxlength="10000"></textarea><details><summary>진도와 메모 가져오기 / 내보내기</summary><p>이 브라우저에 저장을 시도합니다. 다른 기기나 파일로 옮길 때에는 JSON을 복사해 보관하세요. 완료 표시는 숙련도를 판정하지 않습니다.</p><div class="state-actions"><button type="button" id="export">진도 내보내기</button><button type="button" id="import">진도 가져오기</button></div><label for="state-json">진도 JSON</label><textarea id="state-json" maxlength="50000"></textarea></details><p id="save-status" role="status"></p></div>
    <div class="material-panel" id="panel-sources" role="tabpanel" aria-labelledby="tab-sources" data-panel="sources" hidden><h2>참고 자료</h2><ul>{source_items}</ul><details><summary>플레이어의 출처와 라이선스</summary><pre>{h(license_text)}</pre></details></div></section>
    <noscript><section class="material-panel"><h2>JavaScript 없이 읽는 강의 원문</h2>{''.join('<h3>'+h(s['title'])+'</h3><p>'+h(s['transcript'])+'</p>' for s in slides)}<p>{h(data['video_transcript'])}</p><video controls preload="none" aria-label="강의 영상"></video></section></noscript>
    </div><aside id="transcript-rail" aria-label="전체 강의 대본" hidden><div class="rail-heading"><h2>대본</h2><button id="transcript-close" type="button" class="icon-button" aria-label="전체 대본 닫기" title="전체 대본 닫기"></button></div><h3 id="rail-title" tabindex="-1"></h3><div id="rail-copy"></div></aside></main></section><noscript><style>#player-page[hidden],#panel-quiz[hidden],#panel-sources[hidden]{{display:block!important}}#grade,#quiz-result{{display:none}}</style></noscript><footer class="site-footer">🤖 본 강의 자료는 AI가 작성했습니다.</footer><script type="application/json" id="lesson-data">{json.dumps(data,ensure_ascii=False).replace('<','\\u003c')}</script><script>{core}</script><script>{model}</script><script>{narration_script}</script><script>{video_script}</script><script>{presentation_script}</script><script>{controls_script}</script><script>{seek_script}</script><script>{shell_model}</script><script>{theme_script}</script><script>{script}</script></body></html>'''
    import re
    notes='<h2>학습 노트</h2><p id="reading-note">'+h(data['notes'])+'</p>'
    html=re.sub(r'(<div class="material-panel" id="panel-notes"[^>]*>).*?(</div>)',lambda m:m[1]+notes+m[2],html,flags=re.S)
    html=html.replace('이제 다른 응답 순서에서도 예측해 보세요.','배운 내용을 적용해 보세요.').replace('이해 확인에서 새로운 응답 순서를 예측하고, 코스 홈에서 학습 진도를 확인하세요.','이해 확인을 마친 뒤 완료 여부를 직접 표시하세요.')
    if 'video' in published:
        html=html.replace('</body>','<noscript><style>#video-wrap[hidden]{display:block!important}</style></noscript></body>')
    return html
